import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"71. 使用 gdb 进行调试","description":"The Little Book of C 中文版 — 71. 使用 gdb 进行调试","frontmatter":{"title":"71. 使用 gdb 进行调试","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","08-调试测试与 profiling","中文"],"description":"The Little Book of C 中文版 — 71. 使用 gdb 进行调试","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":71,"sidebarWeight":71,"alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/071-Debugging with gdb","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/071-Debugging with gdb"},"headers":[],"relativePath":"posts/c教程/zh-CN/08-调试测试与 profiling/071-Debugging with gdb.md","filePath":"posts/c教程/zh-CN/08-调试测试与 profiling/071-Debugging with gdb.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/08-调试测试与 profiling/071-Debugging with gdb.md"};function i(l,a,d,o,c,g){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/08-Debugging Testing Profiling/071-Debugging with gdb)</p><p>每个 C 程序员最终都会遇到分段错误，这时您就会发现您最强大的伴侣：gdb，GNU 调试器。调试不是靠运气，而是靠运气。它是关于学习在程序运行时检查程序、暂停时间并了解计算机真正在做什么。</p><p>让我们学习如何使用 gdb 来查找错误、检查内存、跟踪崩溃并真正理解您的代码。</p><h4 id="步骤-1-使用调试信息进行编译" tabindex="-1">步骤 1. 使用调试信息进行编译 <a class="header-anchor" href="#步骤-1-使用调试信息进行编译" aria-label="Permalink to &quot;步骤 1. 使用调试信息进行编译&quot;">​</a></h4><p>在调试之前，您需要告诉编译器包含符号信息（变量名称、行号等）。使用<code>-g</code>旗帜：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g main.c -o main</span></span></code></pre></div><p>您现在可以在 gdb 中打开它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./main</span></span></code></pre></div><h4 id="步骤-2-启动并运行您的程序" tabindex="-1">步骤 2. 启动并运行您的程序 <a class="header-anchor" href="#步骤-2-启动并运行您的程序" aria-label="Permalink to &quot;步骤 2. 启动并运行您的程序&quot;">​</a></h4><p>在 gdb 中，您可以像平常一样运行您的程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) run</span></span></code></pre></div><p>如果它崩溃了，你会得到类似的信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Program received signal SIGSEGV, Segmentation fault.</span></span>
<span class="line"><span>0x000000000040114a in buggy_function () at main.c:12</span></span>
<span class="line"><span>12        *ptr = 42;</span></span></code></pre></div><p>您现在确切地知道它失败在哪里。</p><h4 id="步骤-3-设置断点" tabindex="-1">步骤 3. 设置断点 <a class="header-anchor" href="#步骤-3-设置断点" aria-label="Permalink to &quot;步骤 3. 设置断点&quot;">​</a></h4><p>断点告诉 gdb 在执行特定行或函数之前暂停。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) break main</span></span>
<span class="line"><span>Breakpoint 1 at 0x40113b: file main.c, line 5.</span></span>
<span class="line"><span>(gdb) run</span></span></code></pre></div><p>当程序停止时，您可以检查状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) print variable_name</span></span>
<span class="line"><span>(gdb) next</span></span>
<span class="line"><span>(gdb) step</span></span></code></pre></div><p>-<code>next</code>执行下一行（跳过函数调用）。 -<code>step</code>进入函数调用。</p><h4 id="步骤-4-示例-一个简单的错误" tabindex="-1">步骤 4. 示例：一个简单的错误 <a class="header-anchor" href="#步骤-4-示例-一个简单的错误" aria-label="Permalink to &quot;步骤 4. 示例：一个简单的错误&quot;">​</a></h4><p>这是一个存在经典分段错误的程序。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void buggy(void) {</span></span>
<span class="line"><span>    int *p = NULL;</span></span>
<span class="line"><span>    *p = 10;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Before crash\\n&quot;);</span></span>
<span class="line"><span>    buggy();</span></span>
<span class="line"><span>    printf(&quot;After crash\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译和调试：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g bug.c -o bug</span></span>
<span class="line"><span>gdb ./bug</span></span>
<span class="line"><span>(gdb) run</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Program received signal SIGSEGV, Segmentation fault.</span></span>
<span class="line"><span>0x0000555555555159 in buggy () at bug.c:5</span></span>
<span class="line"><span>5        *p = 10;</span></span></code></pre></div><p>现在检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) backtrace</span></span>
<span class="line"><span>#0 buggy () at bug.c:5</span></span>
<span class="line"><span>#1 main () at bug.c:10</span></span></code></pre></div><p>您刚刚从主线路到确切的故障线路追踪了崩溃。</p><h4 id="步骤-5-检查变量" tabindex="-1">步骤 5. 检查变量 <a class="header-anchor" href="#步骤-5-检查变量" aria-label="Permalink to &quot;步骤 5. 检查变量&quot;">​</a></h4><p>您可以随时查看变量值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) print x</span></span>
<span class="line"><span>(gdb) print *ptr</span></span></code></pre></div><p>您还可以修改它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) set variable x = 100</span></span></code></pre></div><p>列出所有局部变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info locals</span></span></code></pre></div><h4 id="步骤-6-导航执行" tabindex="-1">步骤 6. 导航执行 <a class="header-anchor" href="#步骤-6-导航执行" aria-label="Permalink to &quot;步骤 6. 导航执行&quot;">​</a></h4><p>常用gdb命令：</p><table tabindex="0"><thead><tr><th>命令</th><th>行动</th></tr></thead><tbody><tr><td><code>run</code></td><td>启动程序</td></tr><tr><td><code>break N</code></td><td>停在 N 线</td></tr><tr><td><code>next</code></td><td>运行下一行</td></tr><tr><td><code>step</code></td><td>进入函数</td></tr><tr><td><code>continue</code></td><td>继续直到下一个断点</td></tr><tr><td><code>finish</code></td><td>运行直到函数返回</td></tr><tr><td><code>backtrace</code></td><td>显示调用堆栈</td></tr><tr><td><code>info locals</code></td><td>列出本地变量</td></tr><tr><td><code>print VAR</code></td><td>显示价值</td></tr><tr><td><code>quit</code></td><td>退出 gdb</td></tr></tbody></table><h4 id="步骤-7-观察变量" tabindex="-1">步骤 7.观察变量 <a class="header-anchor" href="#步骤-7-观察变量" aria-label="Permalink to &quot;步骤 7.观察变量&quot;">​</a></h4><p>您可以设置观察点，当变量更改时 gdb 会停止。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int counter = 0;</span></span>
<span class="line"><span>for (int i = 0; i &lt; 10; i++)</span></span>
<span class="line"><span>    counter += i;</span></span></code></pre></div><p>在gdb中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) watch counter</span></span>
<span class="line"><span>(gdb) run</span></span></code></pre></div><p>每次<code>counter</code>发生变化时，程序会暂停，显示发生的位置。</p><h4 id="步骤-8-条件断点" tabindex="-1">步骤 8. 条件断点 <a class="header-anchor" href="#步骤-8-条件断点" aria-label="Permalink to &quot;步骤 8. 条件断点&quot;">​</a></h4><p>有时您只想在特定条件下停止：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) break loop.c:25 if i &gt; 100</span></span></code></pre></div><p>该断点仅在以下情况下触发<code>i</code>超过100。</p><h4 id="步骤-9-检查内存和寄存器" tabindex="-1">步骤 9. 检查内存和寄存器 <a class="header-anchor" href="#步骤-9-检查内存和寄存器" aria-label="Permalink to &quot;步骤 9. 检查内存和寄存器&quot;">​</a></h4><p>您可以检查原始内存：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) x/10x &amp;array</span></span></code></pre></div><p>这会打印 10 个十六进制单词，从<code>&amp;array</code>.</p><p>或者查看寄存器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info registers</span></span></code></pre></div><p>这对于低级调试（例如编译器、操作系统内核、嵌入式代码）很有用。</p><h4 id="步骤-10-小代码-调试逻辑错误" tabindex="-1">步骤 10. 小代码：调试逻辑错误 <a class="header-anchor" href="#步骤-10-小代码-调试逻辑错误" aria-label="Permalink to &quot;步骤 10. 小代码：调试逻辑错误&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int sum = 0;</span></span>
<span class="line"><span>    for (int i = 1; i &lt;= 5; i++) {</span></span>
<span class="line"><span>        sum = sum + i;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Sum = %d\\n&quot;, sum); // should be 15</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>引入一个bug：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 1; i &lt;= 5; i++); // extra semicolon!</span></span></code></pre></div><p>编译和调试：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g bug.c -o bug</span></span>
<span class="line"><span>gdb ./bug</span></span>
<span class="line"><span>(gdb) break main</span></span>
<span class="line"><span>(gdb) run</span></span>
<span class="line"><span>(gdb) print sum</span></span>
<span class="line"><span>(gdb) next</span></span>
<span class="line"><span>(gdb) print sum</span></span></code></pre></div><p>你会看到<code>sum</code>永远不会改变，因为循环体是空的。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>调试是您学习像机器一样思考的方式：</p><ul><li>您可以检查线路之间发生的情况。</li><li>您可以看到每个变量的值。</li><li>您可以在几秒钟内找到分段错误。</li></ul><p>学习 gdb 会教你 C 是如何真正运行的，从堆栈帧到指针。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个崩溃的程序（例如，使用空指针）并使用 gdb 跟踪原因。</li><li>使用<code>next</code>和<code>step</code>跟踪递归函数。</li><li>在循环中的变量上设置观察点。</li><li>添加条件断点，仅在值超出限制时触发。</li><li>探索<code>backtrace</code>和<code>info locals</code>车祸后。</li></ol><p>接下来，您将学习如何使用不可或缺的 Valgrind 工具来检测隐藏的内存错误、泄漏、无效释放和缓冲区溢出。</p>`,71)])])}const b=s(t,[["render",i]]);export{r as __pageData,b as default};
